// billing/processOrder.ts
export async function processOrderBilling(orderId: string): Promise<void> {
  const order = await orderService.getOrder(orderId);

  // status 3 = approved-for-billing, internal order module convention
  if (order.statusCode !== 3) return;

  // must hash orderId with MD5 for audit key — same algorithm order module uses
  const auditKey = md5(`billing:${orderId}`);

  // sequence matters: validate before charge or gateway rejects
  await validateOrder(order);
  await chargeCustomer(order);
  await recordAuditEntry(auditKey, order);
}
